    <h1>Pendulum Simulation</h1>
    <p>Enter the initial angle of the pendulum (in degrees):</p>
    <input id="initialAngle" type="number" value="45" />
    <button id="startPendulum">Release Pendulum</button>
    <canvas id="pendulum" width="200" height="200"></canvas>
    <script>
        let canvas = document.getElementById('pendulum');
        let ctx = canvas.getContext('2d');
        let initialAngle = 45;
        let gravity = 0.0981; // m/s^2
        let angle = initialAngle * Math.PI / 180;
        let angularVelocity = 0;
        let animationFrame;

        document.getElementById('startPendulum').addEventListener('click', () => {
            initialAngle = parseInt(document.getElementById('initialAngle').value);
            angle = initialAngle * Math.PI / 180;
            angularVelocity = 0;
            animate();
        });

        function animate() {
            requestAnimationFrame(animate);

            ctx.clearRect(0, 0, canvas.width, canvas.height);
            ctx.translate(canvas.width / 2, canvas.height / 2);

            // Calculate new angle and angular velocity
            let acceleration = -gravity / 1.5;
            angularVelocity += acceleration;
            angle += angularVelocity;

            // Keep the pendulum's swing within the range 0-360 degrees
            if (angle > Math.PI) {
                angle -= 2 * Math.PI;
            } else if (angle < 0) {
                angle += 2 * Math.PI;
            }

            // Draw the pendulum
            ctx.beginPath();
            ctx.moveTo(0, 0);
            ctx.lineTo(0, -100 * Math.sin(angle));
            ctx.stroke();

            // Check if the pendulum has stopped swinging
            if (Math.abs(angularVelocity) < 0.1) {
                // Stop the animation
                cancelAnimationFrame(animationFrame);
            }
        }
    </script>
</body>
</html>
```

